import{_ as a,o as t,c as o,al as i}from"./chunks/framework.BRRmnHXr.js";const u=JSON.parse('{"title":"Input validation and failure behavior","description":"","frontmatter":{},"headers":[],"relativePath":"validation.md","filePath":"validation.md","lastUpdated":null}'),r={name:"validation.md"};function n(d,e,s,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="Input-validation-and-failure-behavior" tabindex="-1">Input validation and failure behavior <a class="header-anchor" href="#Input-validation-and-failure-behavior" aria-label="Permalink to &quot;Input validation and failure behavior {#Input-validation-and-failure-behavior}&quot;">​</a></h1><p>Every public entry point checks its arguments on the host before it launches a kernel that writes user data. A check that fails throws an <code>ArgumentError</code> or a <code>DimensionMismatch</code> that names the offending argument, so the input data are left unchanged. This page lists the policies these checks enforce.</p><h2 id="Precision,-backend,-and-shape" tabindex="-1">Precision, backend, and shape <a class="header-anchor" href="#Precision,-backend,-and-shape" aria-label="Permalink to &quot;Precision, backend, and shape {#Precision,-backend,-and-shape}&quot;">​</a></h2><ul><li><p><strong>Precision.</strong> Every floating-point array passed together with a particle container must have the same scalar element type as the particle coordinates. Mixed precision is rejected, not converted, because a narrowing conversion inside a kernel is silent. Scalars such as <code>dt</code> are converted to the particle precision.</p></li><li><p><strong>Metal and Float64.</strong> Metal has no <code>Float64</code>. Constructors such as <code>init_particles</code>, <code>PhaseRatios</code>, <code>init_passive_markers</code>, <code>init_markerchain</code>, and <code>init_marker_surface</code> throw on the Metal backend when the grids or the requested type are <code>Float64</code>.</p></li><li><p><strong>Backend.</strong> Every array argument must live on the backend of the particles. Coordinate ranges carry no device storage and are accepted on every backend.</p></li><li><p><strong>Grid fields.</strong> Grid fields must have the size of the grid they are sampled on: the vertex grid for <code>particle2grid!</code>/<code>grid2particle!</code>, the cell centers for <code>particle2centroid!</code>/<code>centroid2particle!</code>. Along a direction with <code>ghost_i = true</code> (the default) the field includes the ghost nodes; along a direction with <code>ghost_i = false</code> it holds only the physical nodes.</p></li><li><p><strong>Particle fields.</strong> Per-particle fields must be <code>CellArray</code>s with the cell layout of <code>particles.index</code>, that is, the same grid size and the same number of slots per cell. Fields that hold <code>NaN</code> in empty slots (<code>args</code> of <code>move_particles!</code> and the injection routines) must be floating point.</p></li><li><p><strong>Tuples.</strong> A destination and its source must both be single fields or tuples of the same length.</p></li><li><p><strong>Velocity.</strong> <code>V</code> must be a tuple with one component per dimension, and <code>V[d]</code> must have the size of the staggered grid <code>grid_vi[d]</code>.</p></li></ul><h2 id="Grids" tabindex="-1">Grids <a class="header-anchor" href="#Grids" aria-label="Permalink to &quot;Grids {#Grids}&quot;">​</a></h2><p>A coordinate vector must hold at least two finite, strictly increasing entries, and all grid coordinates must share one floating-point type. For <code>init_particles</code>, the off-diagonal staggered grids <code>grid_vi[d][i]</code> are the cell-center grids of direction <code>i</code> extended by one ghost center on each side, so they have one more entry than the vertex grid <code>grid_vi[i][i]</code>.</p><h2 id="Aliasing" tabindex="-1">Aliasing <a class="header-anchor" href="#Aliasing" aria-label="Permalink to &quot;Aliasing {#Aliasing}&quot;">​</a></h2><p>Source and destination arrays must not share memory. The checks reject:</p><ul><li><p>the particle coordinates among the companion fields <code>args</code> of <code>move_particles!</code> and the injection routines, and any two entries of <code>args</code> that share memory;</p></li><li><p>a grid field and a particle field of an interpolation call that share memory, and entries of a tuple-valued destination that share memory;</p></li><li><p><code>F</code> and <code>F0</code> of <code>semilagrangian_advection!</code> that share memory;</p></li><li><p>the grid field, marker field, and buffer of a passive-marker scatter that share memory.</p></li></ul><h2 id="Coordinates-and-displacement" tabindex="-1">Coordinates and displacement <a class="header-anchor" href="#Coordinates-and-displacement" aria-label="Permalink to &quot;Coordinates and displacement {#Coordinates-and-displacement}&quot;">​</a></h2><ul><li><p><strong>Material particles.</strong> <code>move_particles!</code> rejects <code>NaN</code> in any active coordinate slot, because <code>NaN</code> means an invalid velocity field or time step. An infinite coordinate is valid input: it marks a particle that left the velocity grid during advection, and <code>move_particles!</code> removes it like any other particle outside the domain.</p></li><li><p><strong>Boundary escape.</strong> Particles that leave a non-periodic direction are discarded. Along a periodic direction they wrap to the opposite side; the ghost cells of a periodic direction must be empty when <code>move_particles!</code> is called.</p></li><li><p><strong>Displacement.</strong> A particle may cross any number of cells in one call to <code>move_particles!</code>. Large jumps are slower, not rejected; see the <a href="/JustPIC.jl/previews/PR376/particles#JustPIC.move_particles!"><code>move_particles!</code></a> docstring. If a destination cell is full, the particle and its companion fields are dropped; <code>verbose = true</code> prints the number of dropped particles.</p></li><li><p><strong>Passive markers.</strong> Passive markers have no occupancy mask. <code>init_passive_markers</code> requires finite coordinates, and interpolation and advection require every marker to lie inside the grid. <code>advection!</code> stops markers on the boundary instead of moving them outside.</p></li><li><p><strong>Time step and integrator.</strong> <code>dt</code> must be finite. The advection routines accept <code>Euler</code>, <code>RungeKutta2</code>, and <code>RungeKutta4</code>; any other integrator is rejected.</p></li></ul><h2 id="Empty-support" tabindex="-1">Empty support <a class="header-anchor" href="#Empty-support" aria-label="Permalink to &quot;Empty support {#Empty-support}&quot;">​</a></h2><p>A grid node whose interpolation stencil contains no particle has no data. JustPIC marks such a node with <code>NaN</code> instead of inventing a value. This applies to:</p><ul><li><p><code>particle2grid!</code> and <code>particle2centroid!</code> for material particles;</p></li><li><p><code>particle2grid!</code> for passive markers;</p></li><li><p><code>update_phase_ratios!</code>, <code>phase_ratios_center!</code>, <code>phase_ratios_vertex!</code>, and the face and midpoint phase ratios.</p></li></ul><p>Test for <code>NaN</code> with <code>isnan</code> to detect empty support. Keep particle occupancy high enough, for example with <code>inject_particles!</code>, to avoid it.</p><h2 id="Phase-labels" tabindex="-1">Phase labels <a class="header-anchor" href="#Phase-labels" aria-label="Permalink to &quot;Phase labels {#Phase-labels}&quot;">​</a></h2><p>A phase label must be an integer value in <code>1:nphases</code>, where <code>nphases</code> is the number of phases of the <code>PhaseRatios</code> object. Phase labels may be stored with a floating-point element type. The phase-ratio routines count invalid labels over the active slots and throw if there is any.</p><h2 id="MPI-and-ghost-layout" tabindex="-1">MPI and ghost layout <a class="header-anchor" href="#MPI-and-ghost-layout" aria-label="Permalink to &quot;MPI and ghost layout {#MPI-and-ghost-layout}&quot;">​</a></h2><ul><li><p><code>update_cell_halo!</code> requires an initialized ImplicitGlobalGrid.</p></li><li><p>Passive markers do not support MPI runs with more than one rank.</p></li><li><p>Grid fields follow the ghost-node layout described in <a href="./grid_layouts">Grid layouts</a>.</p></li></ul><h2 id="Unsupported-combinations" tabindex="-1">Unsupported combinations <a class="header-anchor" href="#Unsupported-combinations" aria-label="Permalink to &quot;Unsupported combinations {#Unsupported-combinations}&quot;">​</a></h2><p>The <a href="./support_matrix">support matrix</a> lists the combinations marked <code>Unsupported</code>. The entry points reject these with an error instead of running an incorrect method:</p><ul><li><p><code>Float64</code> on Metal, for every constructor;</p></li><li><p>passive markers in MPI runs with more than one rank;</p></li><li><p>advection integrators other than <code>Euler</code>, <code>RungeKutta2</code>, and <code>RungeKutta4</code>;</p></li><li><p>2D or 3D mismatches between the phase ratios and the particles, and 3D-only midpoint phase ratios requested for 2D particles.</p></li></ul>',22)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
